{
  "status": "SUPPORTED",
  "task_summary": "Locate fastening parts and tools in storage, perform the fastening on the target object, and return the tool to the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "robot_agent",
        "entity_kind": "OBJECT",
        "function": "Performs all manipulation, searching, and placement tasks.",
        "required_count": 1
      ,
        "binding_policy": "SHARED",
        "candidate_categories": ["robotic arm", "manipulator"],
        "required_properties": ["grasping ability", "mobility"]
      },
      {
        "id": "fastening_target",
        "entity_kind": "OBJECT",
        "function": "The object or assembly that requires the fastening action.",
        "required_count": 1
      ,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["assembly", "part", "object"],
        "required_properties": ["has fastening interface"]
      },
      {
        "id": "fastening_component",
        "entity_kind": "OBJECT",
        "function": "The hardware piece (e.g., screw, bolt) used to join the target.",
        "required_count": 1
      ,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["screw", "bolt", "nut", "pin"],
        "required_properties": ["compatible with fastening_target", "drivable"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to drive or secure the component.",
        "required_count": 1
      ,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "wrench", "driver"],
        "required_properties": ["fits fastening_component"]
      },
      {
        "id": "workbench_surface",
        "entity_kind": "REGION",
        "function": "The destination for placing the tool after the task.",
        "required_count": 1
      ,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk", "surface"],
        "required_properties": ["flat", "stable"]
      },
      {
        "id": "searchable_storage",
        "entity_kind": "REGION",
        "function": "Enclosed areas containing the required components and tools.",
        "required_count": 1
      ,
        "binding_policy": "SHARED",
        "candidate_categories": ["drawer", "cabinet", "compartment"],
        "required_properties": ["enclosed", "openable"]
      }
    ],
    "functional_relations": [
      {
        "id": "connection_goal",
        "relation": "fastening_component connects to fastening_target",
        "participant_roles": ["fastening_component", "fastening_target"]
      ,
        "required": true
      },
      {
        "id": "application_process",
        "relation": "fastening_tool applies fastening_component to fastening_target",
        "participant_roles": ["fastening_tool", "fastening_component", "fastening_target"]
      ,
        "required": true
      },
      {
        "id": "cleanup_state",
        "relation": "fastening_tool rests on workbench_surface",
        "participant_roles": ["fastening_tool", "workbench_surface"]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "locate_parts",
        "operation": "Search storage for components and tools",
        "participant_roles": ["robot_agent", "searchable_storage", "fastening_component", "fastening_tool"]
      ,
        "operation_count": 1
      },
      {
        "id": "execute_fastening",
        "operation": "Attach component to target using tool",
        "participant_roles": ["robot_agent", "fastening_tool", "fastening_component", "fastening_target"]
      ,
        "operation_count": 1
      },
      {
        "id": "deposit_tool",
        "operation": "Place tool on workbench",
        "participant_roles": ["robot_agent", "fastening_tool", "workbench_surface"]
      ,
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "robot_agent": [
        {
          "label": "white_robotic_arm",
          "visual_description": "A large white robotic arm is visible in the foreground."
        }
      ],
      "fastening_target": [
        {
          "label": "yellow_blue_object",
          "visual_description": "A yellow and blue object sits on a black tray on the wooden table."
        }
      ],
      "workbench_surface": [
        {
          "label": "wooden_table",
          "visual_description": "A wooden table with drawers underneath."
        }
      ],
      "searchable_storage": [
        {
          "label": "under_desk_drawers",
          "visual_description": "Two blue drawers are visible under the table."
        },
        {
          "label": "blue_cabinet",
          "visual_description": "A tall blue cabinet is visible behind the table."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "searchable_storage",
        "label": "Drawers and Cabinet",
        "visual_description": "Closed drawers under the desk and a closed cabinet door.",
        "reason": "These enclosed structures are the most probable locations for the missing fastening components and tools."
      }
    ],
    "inspection_order": [
      "searchable_storage"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
